import React, {useState} from 'react';
import Box from '@mui/material/Box';
import { useTranslation } from 'react-i18next';
import List from '@mui/material/List';
import GitHubIcon from '@mui/icons-material/GitHub';
import CallIcon from '@mui/icons-material/Call';
import EmailIcon from '@mui/icons-material/Email';
import LinkedInIcon from '@mui/icons-material/LinkedIn';
import LocationOnIcon from '@mui/icons-material/LocationOn';
import { useThemeContext } from '../Burger/themeContext';
import themes from './../Burger/theme';
import Typography from '@mui/joy/Typography';
import TextField from '@mui/material/TextField';
import { DarkMode } from '@mui/icons-material';
import Button from '@mui/joy/Button';
import { useFormik } from 'formik';
import * as Yup from 'yup';
import { styled } from '@mui/system';
import emailjs from '@emailjs/browser';
import Alert from '@mui/material/Alert';
import AlertTitle from '@mui/material/AlertTitle';
import Link from '@mui/material/Link';
import { Slide, toast, ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import { MapContainer, TileLayer, Marker, Popup } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import L from 'leaflet';

const Contact = () => {
  const { t } = useTranslation();
  const {darkMode} = useThemeContext();

  const icons = (
    <List sx={{display:"flex", flexWrap:"wrap", width: '200px', justifyContent: 'space-between'}}>
        <GitHubIcon />
        <CallIcon />
        <EmailIcon />
        <LinkedInIcon />
    </List>
  )

  const CustomButton = styled(Button)({
    backgroundColor: themes.dark.primaryColor,
    borderColor: themes.dark.primaryColor,
    margin: '2%',
    '&:hover': {
      borderColor: '#754de8',
      backgroundColor: '#000000',
    },
  });

  const validationSchema = Yup.object({
    firstName: Yup.string()
      .max(15, 'Doit être 15 caractères ou moins')
      .required('Champ requis'),
    lastName: Yup.string()
      .max(20, 'Doit être 20 caractères ou moins')
      .required('Champ requis'),
    email: Yup.string()
      .email('Email invalide')
      .required('Champ requis'),
    message: Yup.string()
      .required('Champ requis'),
  });
  
  const MyForm = () => {

    const formik = useFormik({
      initialValues: {
        firstName: '',
        lastName: '',
        email: '',
        message: '',
      },
      validationSchema: validationSchema,
      onSubmit: (values) => {
        emailjs.send('service_o4il1by', 'template_n1x56ie', values, 'K7q1JB9_2et-A-NdO')
          .then((response) => {
            console.log('E-mail envoyé avec succès!', response);
            formik.resetForm();
            //setShowSuccessAlert(true);
            toast.success('E-mail envoyé avec succès !', {
              position: "bottom-right",
              autoClose: 5000,
              hideProgressBar: false,
              closeOnClick: true,
              pauseOnHover: true,
              draggable: true,
              progress: undefined,
              theme: darkMode? "dark" : "light",
              transition: Slide,
              });
          setTimeout(() => {
            //setShowSuccessAlert(false);
          }, 5000);
          })
          .catch((error) => {
            console.error('Erreur lors de l\'envoi de l\'e-mail:', error);
          });
      },
    });
  
    return (
      <>
      {/* {showSuccessAlert && (
        <Alert severity="success">
          <AlertTitle>Success</AlertTitle>
          Le mail a été envoyé avec succès!
        </Alert>
      )} */}
      <ToastContainer />
      <form onSubmit={formik.handleSubmit}>
        <CustomTextField
          fullWidth
          id="firstName"
          name="firstName"
          label="Prénom *"
          value={formik.values.firstName}
          onChange={formik.handleChange}
          error={formik.touched.firstName && Boolean(formik.errors.firstName)}
          helperText={formik.touched.firstName && formik.errors.firstName}
        />
        <CustomTextField
          fullWidth
          id="lastName"
          name="lastName"
          label="Nom *"
          value={formik.values.lastName}
          onChange={formik.handleChange}
          error={formik.touched.lastName && Boolean(formik.errors.lastName)}
          helperText={formik.touched.lastName && formik.errors.lastName}
        />
        <CustomTextField
          fullWidth
          id="email"
          name="email"
          label="Email *"
          value={formik.values.email}
          onChange={formik.handleChange}
          error={formik.touched.email && Boolean(formik.errors.email)}
          helperText={formik.touched.email && formik.errors.email}
        />
        <CustomTextField
          fullWidth
          id="message"
          name="message"
          label="Message *"
          value={formik.values.message}
          onChange={formik.handleChange}
          error={formik.touched.message && Boolean(formik.errors.message)}
          helperText={formik.touched.message && formik.errors.message}
          multiline
          rows={5}
          InputProps={{
            style: {
              color: darkMode ? themes.dark.text : themes.light.textColor
            }
          }}
        />
        <CustomButton type="submit" size="lg" variant="solid" sx={{marginRight: '20px'}}>Envoyer</CustomButton>
      </form>
      </>
    );
  };


  const CustomTextField = (props) => {

    return (
      <TextField
        {...props}
      InputLabelProps={{
        style: {
          color: darkMode? themes.dark.text : themes.light.textColor,
        },
      }}
        sx={{
          input: { color: darkMode? themes.dark.text : themes.light.textColor },
          margin: '2%',
          '& .MuiOutlinedInput-root': {
            '& fieldset': {
              borderColor: 'var(--TextField-brandBorderColor)',
              color: darkMode? themes.dark.primaryColor : themes.light.primaryColor,
            },
            '&:hover fieldset': {
              borderColor: 'var(--TextField-brandBorderHoverColor)',
            },
            '&.Mui-focused fieldset': {
              borderColor: 'var(--TextField-brandBorderFocusedColor)',
              color: darkMode? themes.dark.primaryColor : themes.light.primaryColor,

            },
          },
        }}
      />
    );
  };

  const markerIcon = new L.Icon({
    iconUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon.png',
    iconSize: [25, 41],
    iconAnchor: [12, 41],
  });

  return (
    <Box
      component="main"
      sx={{
        flexGrow: 1,
        p: 3,
        backgroundColor: darkMode ? themes.dark.backgroundColor : themes.light.backgroundColor,
        minWidth: '100%',
        color: darkMode ? 'white' : '#000000',
        minHeight: '100vh'
      }}
    >
      <Box sx={{margin: '3%', bgcolor: darkMode? themes.dark.encadre : themes.light.encadre, borderRadius: '10px', padding: '3%'}}>
          <Typography style={{ color: darkMode? themes.dark.text : themes.light.textColor, textAlign: 'center', marginBottom: '15px', fontSize: '2.6rem' }}>{t('CONTACT')}</Typography>
          <Box sx={{display:'flex', flexWrap:'wrap', justifyContent:'space-between'}}>
          <Box sx={{margin: '3%', width: '100%', maxWidth: '43%'}}>
          <MyForm />
          </Box>

        <Box sx={{margin: '3%', width: '100%', maxWidth: '43%'}}>
          <MapContainer 
            center={[43.6167, 7.0667]} 
            zoom={15} 
            style={{ height: '100%', minHeight: '300px', width: '100%', borderRadius: '10px' }}
          >
            <TileLayer
              url={darkMode 
                ? 'https://{s}.tile.openstreetmap.fr/osmfr/{z}/{x}/{y}.png' 
                : 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png'}
              attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
            />
            <Marker position={[43.6167, 7.0667]} icon={markerIcon}>
              <Popup>
                Université Côte d'Azur - Campus Sophia Tech
              </Popup>
            </Marker>
          </MapContainer>
        </Box>
        </Box>
        </Box>
      </Box>
  );
};

export default Contact;

