import React from 'react';
import Box from '@mui/material/Box';
import { useTranslation } from 'react-i18next';
import { useThemeContext } from '../Burger/themeContext';
import themes from '../Burger/theme';
import Accordion from '@mui/material/Accordion';
import AccordionActions from '@mui/material/AccordionActions';
import AccordionSummary from '@mui/material/AccordionSummary';
import AccordionDetails from '@mui/material/AccordionDetails';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import civ from '../../img/civ.jpg';
import efrei from '../../img/efreicampus-8334.jpg';
import unica from '../../img/iut.jpg';
import Typography from '@mui/joy/Typography';
import Card from '@mui/joy/Card';
import CardCover from '@mui/joy/CardCover';
import CardContent from '@mui/joy/CardContent';
import LocationOnRoundedIcon from '@mui/icons-material/LocationOnRounded';
import { useTheme } from '@mui/material/styles';
import useMediaQuery from '@mui/material/useMediaQuery';

function Formation() {
  const { t } = useTranslation();
  const {darkMode} = useThemeContext();
  const isScreenWide = useMediaQuery('(min-width:600px)');

  const styles = {
    accordion: {
      backgroundColor: darkMode? themes.dark.encadre : themes.light.encadre,
      borderRadius: '10px',
      marginBottom: '10px',
    },
    accordionSummary: {
      backgroundColor: darkMode? themes.dark.encadre : themes.light.encadre,
      color: 'white',
      fontWeight: 'bold',
    },
    accordionDetails: {
      backgroundColor: darkMode? themes.dark.encadre : themes.light.encadre,
      color: 'white',
      padding: '10px',
    }
  };

  return (
    <Box
      component="main"
      sx={{
        flexGrow: 1,
        p: 3,
        backgroundColor: darkMode? themes.dark.backgroundColor : themes.light.backgroundColor,
        color: darkMode? themes.dark.text : themes.light.textColor,
        minHeight: '100vh'
      }}
    >
      <Box sx={{ margin: '3%'}}>
          <Box sx={{ display: 'flex', flexWrap: 'wrap', justifyContent: 'center', bgcolor: darkMode? themes.dark.encadre : themes.light.encadre, borderRadius: '10px', padding: '4%'}}>
          <Typography  textColor={darkMode? themes.dark.text : themes.light.textColor} style={{ fontSize: '2.5rem'}}>{t('FOMATION')}</Typography>
        <Box sx={{height: '100%', display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', gap: '20px', marginTop: '4%'}}> 
        <Accordion style={styles.accordionDetails} sx={{width: isScreenWide ? '98%' : '85%', margin: '5px'}}>
        <AccordionSummary
          expandIcon={<ExpandMoreIcon style={{ color: darkMode? themes.dark.primaryColor : themes.light.primaryColor }} />}
          aria-controls="panel1-content"
          id="panel1-header"
          sx={{ display: 'flex', alignItems: 'center'}}
        >
          <Box sx={{display: 'flex', flexDirection: 'column', width: '100%'}}>
          <Typography  textColor={darkMode? themes.dark.text : themes.light.textColor} style={{ fontSize: '2rem', textAlign: 'left'}}>{t('IUT')}</Typography>
          <Typography  textColor={darkMode? themes.dark.text : themes.light.textColor} style={{ fontSize: '1rem', textAlign: 'left'}}>{t('DUT')}</Typography>
          {!isScreenWide ? (
          <Typography textColor={darkMode? themes.dark.primaryColor : themes.light.primaryColor} style={{ fontSize: '1.3rem', textAlign: 'left'}}>2023 - 2024</Typography>) : null}
          </Box>
          {isScreenWide ? (
            <Box sx={{width: isScreenWide ? '200px' : 'auto', display: 'flex', alignItems: 'center', justifyContent: 'center'}}>
          <Typography textColor={darkMode? themes.dark.primaryColor : themes.light.primaryColor} style={{ fontSize: '1.6rem', textAlign: 'left'}}>2023 - 2024</Typography></Box>) : null}
        </AccordionSummary>
        <AccordionDetails >

        <Box sx={{display: 'flex', flexWrap: 'wrap', justifyContent: 'space-between', gap: '100px'}}>
        <Box sx={{width: {xs:'80%', sm:'55%'}}}><Typography  textColor={darkMode? themes.dark.text : themes.light.textColor} style={{ fontSize: '1rem', textAlign: 'left'}}>{t('DESCIUT')}</Typography></Box>
          <Card sx={{ height: isScreenWide ? '200px' : '100px', width: isScreenWide ? '330px' : '175px', border: 'none' }}>
        <CardCover>
          <img
            src={unica}
            loading="lazy"
            alt=""
          />
        </CardCover>
        <CardCover
          sx={{
            background:
              'linear-gradient(to top, rgba(0,0,0,0.4), rgba(0,0,0,0) 200px), linear-gradient(to top, rgba(0,0,0,0.3), rgba(0,0,0,0) 300px)',
          }}
        />
        <CardContent sx={{ justifyContent: 'flex-end' }}>
          <Typography
            startDecorator={<LocationOnRoundedIcon />}
            textColor="neutral.300"
          >
            Institu Universitaire technologique
          </Typography>
        </CardContent>
      </Card>
      </Box>
        </AccordionDetails>
      </Accordion>
      <Accordion style={styles.accordionDetails} sx={{width: isScreenWide ? '98%' : '85%', margin: '5px'}}>
        <AccordionSummary
          expandIcon={<ExpandMoreIcon style={{ color: darkMode? themes.dark.primaryColor : themes.light.primaryColor }} />}
          aria-controls="panel1-content"
          id="panel1-header"
          sx={{ display: 'flex', alignItems: 'center' }}
        >
          <Box sx={{display: 'flex', flexDirection: 'column', width: '98%'}}>
          <Typography  textColor={darkMode? themes.dark.text : themes.light.textColor} style={{ fontSize: '2rem', textAlign: 'left'}}>Efrei</Typography>
          <Typography  textColor={darkMode? themes.dark.text : themes.light.textColor} style={{ fontSize: '1rem', textAlign: 'left'}}>{t('EFREEIDIPLOME')}</Typography>
          {!isScreenWide ? (
          <Typography textColor={darkMode? themes.dark.primaryColor : themes.light.primaryColor} style={{ fontSize: '1.3rem', textAlign: 'left'}}>2022 - 2023</Typography>) : null}
          </Box>
          {isScreenWide ? (
            <Box sx={{width: isScreenWide ? '200px' : 'auto', display: 'flex', alignItems: 'center', justifyContent: 'center'}}>
          <Typography textColor={darkMode? themes.dark.primaryColor : themes.light.primaryColor} style={{ fontSize: '1.6rem', textAlign: 'left'}}>2022 - 2023</Typography></Box>) : null}
        </AccordionSummary>
        <AccordionDetails>
        <Box sx={{display: 'flex', flexWrap: 'wrap', justifyContent: 'space-between', gap: '10%'}}>
          <Card sx={{ minHeight: '200px', width: 320, border: 'none' }}>
        <CardCover>
          <img
            src={efrei}
            loading="lazy"
            alt=""
          />
        </CardCover>
        <CardCover
          sx={{
            background:
              'linear-gradient(to top, rgba(0,0,0,0.4), rgba(0,0,0,0) 200px), linear-gradient(to top, rgba(0,0,0,0.3), rgba(0,0,0,0) 300px)',
          }}
        />
        <CardContent sx={{ justifyContent: 'flex-end' }}>
          <Typography
            startDecorator={<LocationOnRoundedIcon />}
            textColor="neutral.300"
          >
            EFREI - Grande Ecole du Numérique
          </Typography>
        </CardContent>
      </Card>
      <Box sx={{width: '55%'}}>
        <Typography  textColor={darkMode? themes.dark.text : themes.light.textColor} style={{ fontSize: '1rem', textAlign: 'left'}}>{t('EFREIDESC1')}</Typography><br></br>
        <Typography  textColor={darkMode? themes.dark.text : themes.light.textColor} style={{ fontSize: '1rem', textAlign: 'left'}}>{t('EFREIDESC2')}</Typography></Box>
        </Box>
        </AccordionDetails>
      </Accordion>
      <Accordion style={styles.accordionDetails} sx={{width: isScreenWide ? '98%' : '85%', margin: '5px'}}>
        <AccordionSummary
          expandIcon={<ExpandMoreIcon style={{ color: darkMode? themes.dark.primaryColor : themes.light.primaryColor }} />}
          aria-controls="panel1-content"
          id="panel1-header"
          sx={{ display: 'flex', alignItems: 'center' }}
        >
          <Box sx={{display: 'flex', flexDirection: 'column', width: '98%'}}>
          <Typography  textColor={darkMode? themes.dark.text : themes.light.textColor} style={{ fontSize: '2rem', textAlign: 'left'}}>{t('LIV')}</Typography>
          <Typography  textColor={darkMode? themes.dark.text : themes.light.textColor} style={{ fontSize: '1rem', textAlign: 'left'}}>{t('BAC')}</Typography>
          {!isScreenWide ? (
          <Typography textColor={darkMode? themes.dark.primaryColor : themes.light.primaryColor} style={{ fontSize: '1.3rem', textAlign: 'left'}}>2019 - 2022</Typography>) : null}
          </Box>
          {isScreenWide ? (
            <Box sx={{width: isScreenWide ? '200px' : 'auto', display: 'flex', alignItems: 'center', justifyContent: 'center'}}>
          <Typography textColor={darkMode? themes.dark.primaryColor : themes.light.primaryColor} style={{ fontSize: '1.6rem', textAlign: 'left'}}>2019 - 2022</Typography></Box>) : null}
        </AccordionSummary>
        <AccordionDetails>
        <Box sx={{display: 'flex', flexWrap: 'wrap', justifyContent: 'space-between', gap: '100px'}}>
        <Box sx={{width: '55%'}}><Typography  textColor={darkMode? themes.dark.text : themes.light.textColor} style={{ fontSize: '1rem', textAlign: 'left'}}>{t('LIVDESC')}</Typography></Box>
          <Card sx={{ minHeight: '200px', width: 330, border: 'none' }}>
        <CardCover>
          <img
            src={civ}
            loading="lazy"
            alt=""
          />
        </CardCover>
        <CardCover
          sx={{
            background:
              'linear-gradient(to top, rgba(0,0,0,0.4), rgba(0,0,0,0) 200px), linear-gradient(to top, rgba(0,0,0,0.1), rgba(0,0,0,0) 300px)',
          }}
        />
        <CardContent sx={{ justifyContent: 'flex-end' }}>
          <Typography
            startDecorator={<LocationOnRoundedIcon />}
            textColor="neutral.300"
          >
            Centre International de Valbonne {/*TODO*/}
          </Typography>
        </CardContent>
      </Card>
      </Box>
        </AccordionDetails>
      </Accordion>
      </Box>
        </Box>
        </Box>
    </Box>

  );
};

export default Formation;