import * as React from 'react';
import Card from '@mui/material/Card';
import CardActions from '@mui/material/CardActions';
import CardContent from '@mui/material/CardContent';
import CardMedia from '@mui/material/CardMedia';
import Button from '@mui/material/Button';
import Typography from '@mui/material/Typography';
import List from '@mui/material/List';
import Dialog from '@mui/material/Dialog';
import { styled } from '@mui/material/styles';
import { useThemeContext } from './../Burger/themeContext';
import themes from './../Burger/theme'
import spaceSquad from './../../img/spacesquad1PNG.PNG';
import portfolioCouverture from './../../img/portfolio1.JPG';
import reactCouverture from './../../img/reactapp1.JPG';
import pythonCouverture from './../../img/python1PNG.png';
import javaCouverture from './../../img/javarpg.jpg';
import { DarkMode } from '@mui/icons-material';
import android from './../../img/android.jpg'
import board from './../../img/board.jpg'
import foules from './../../img/foules.png'
import useMediaQuery from '@mui/material/useMediaQuery';
import { Portfolio } from './popup/portfolio';
import { Android } from './popup/android';
import { ReactNode } from './popup/react';
import { Java } from './popup/java';
import { Web } from './popup/web';
import DialogActions from '@mui/material/DialogActions';
import IconButton from '@mui/material/IconButton';
import CloseIcon from '@mui/icons-material/Close';
import DialogTitle from '@mui/material/DialogTitle';
import { Divider } from '@mui/material';
import { Iot } from './popup/iot';
import { Math } from './popup/math';

const cardData = [
  {
    id: 1,
    title: 'IOT',
    image: board,
    description: "Réalisation d'un bracelet connecté avec un capteur bpm, température, oxygen dans le sang.",
    date: 'Janvier - Février 2025',
  },
  {
    id: 2,
    title: 'Modélisation Mathématiques',
    image: foules,
    description: "Etude et développement de programmes sur la dynamique des foules.",
    date: 'Janvier - Février 2025',
  },
  {
    id: 3,
    title: 'Android Studio',
    image: android,
    description: "Développement d'une appplication mobilde de vente en ligne. ",
    date: 'Juin 2024',
  },
  {
    id: 4,
    title: 'Portfolio',
    image: portfolioCouverture,
    description: 'Développement React de mon portfolio & déploiement continue.',
    date: '2023 - 2024',
  },
  {
    id: 5,
    title: 'Web Site',
    image: spaceSquad,
    description: "Développement d'un site web et de jeux sur l'espace.",
    date: 'Novembre 2022',
  },
];

const CardsContainer = ({ darkMode, themes, handleClickOpen }) => {
  const isScreenWide = useMediaQuery('(min-width:1600px)');

  return (
    <div style={{ display: 'flex', flexWrap: 'wrap', gap: isScreenWide? '2%' : '0', justifyContent: 'center'}}>
      {cardData.map((data, index) => (
        <Card
          key={index}
          onClick={() => handleClickOpen(data.id)}
          sx={{
            maxWidth: 345,
            margin: '20px',
            borderRadius: 2,
            boxShadow: ` 0px 0px 15px 0px rgba(255, 2, 102, 0.4)`,
            transition: '0.2s',
            '&:hover': { transform: 'scale(1.05)' },
          }}
        >
          <CardMedia sx={{ height: 140 }} image={data.image} title={data.title} />
          <CardContent sx={{ backgroundColor: darkMode ? themes.dark.cardBackgroundColor : themes.light.cardBackgroundColor }}>
            <Typography gutterBottom variant="h5" component="div" sx={{ color: darkMode? themes.dark.text : themes.light.textColor }}>
              {data.title}
            </Typography>
            <Typography variant="body2" sx={{ color : darkMode? themes.dark.text : themes.light.textColor}}>
              {data.description}
            </Typography>
          </CardContent>
          {!darkMode? <Divider inset="context" /> : null}
          <CardContent sx={{backgroundColor: darkMode ? themes.dark.cardBackgroundColor : themes.light.cardBackgroundColor}}>
          <Typography variant="body2" sx={{ color : darkMode? themes.dark.primaryColor : themes.light.primaryColor, fontSize:'1rem'}}>{data.date}</Typography>
          </CardContent>
        </Card>
      ))}
    </div>
  );
};

const BootstrapDialog = styled(Dialog)(({ theme }) => ({
  '& .MuiDialog-paper': {
    backgroundColor: 'white', // Couleur de fond de la pop-up
    maxWidth: '60%', // Définir la largeur maximale désirée, par exemple 80%
  },
  '& .MuiDialogContent-root': {
    padding: theme.spacing(2),
  },
  '& .MuiDialogActions-root': {
    padding: theme.spacing(1),
  },
}));

function MediaCard() {
  const [openAndroid, setOpenAndroid] = React.useState(false);
  const [openPortfolio, setOpenPortfolio] = React.useState(false);
  const [openReact, setOpenReact] = React.useState(false);
  const [openJava, setOpenJava] = React.useState(false);
  const [openWeb, setOpenWeb] = React.useState(false);
  const [openIOT, setOpenIOT] = React.useState(false);
  const [openMath, setOpenMath] = React.useState(false);

  const {darkMode} = useThemeContext();

  const handleClickOpen = (id) => {
    switch(id){
      case 1:
        setOpenIOT(true);
        break;
      case 2:
        setOpenMath(true);
        break;
      case 3:
        setOpenAndroid(true);
        break;
      case 4:
        setOpenPortfolio(true);
        break;
      case 5:
        setOpenWeb(true);
        break;
    }
  };

  const handleCloseIOT = () => {
    setOpenIOT(false);
  };

  const handleCloseMath = () => {
    setOpenMath(false);
  };

  const handleCloseAndroid = () => {
    setOpenAndroid(false);
  };

  const handleClosePortfolio = () => {
    setOpenPortfolio(false);
  };

  const handleCloseReact = () => {
    setOpenReact(false);
  };

  const handleCloseJava = () => {
    setOpenJava(false);
  };

  const handleCloseWeb = () => {
    setOpenWeb(false);
  };


    return (
      <React.Fragment>
        <List>
          <CardsContainer darkMode={darkMode} themes={themes} handleClickOpen={handleClickOpen}/>
        </List>
        <BootstrapDialog
        onClose={handleCloseIOT}
        aria-labelledby="customized-dialog-title"
        open={openIOT}
      >
        <DialogTitle sx={{ m: 0, p: 2, bgcolor: darkMode ? themes.dark.backgroundColor : themes.light.backgroundColor, color: darkMode ? themes.dark.text : themes.light.textColor }} id="customized-dialog-title">
          IOT
        </DialogTitle>
        <IconButton
          aria-label="close"
          onClick={handleCloseIOT}
          sx={{
            position: 'absolute',
            right: 8,
            top: 8,
            color: (theme) => theme.palette.grey[500],
          }}
        >
          <CloseIcon />
        </IconButton>
        <Iot darkMode={darkMode}/>
      </BootstrapDialog>

        <BootstrapDialog
        onClose={handleCloseMath}
        aria-labelledby="customized-dialog-title"
        open={openMath}
      >
        <DialogTitle sx={{ m: 0, p: 2, bgcolor: darkMode ? themes.dark.backgroundColor : themes.light.backgroundColor, color: darkMode ? themes.dark.text : themes.light.textColor }} id="customized-dialog-title">
          Modélisation Mathématiques
        </DialogTitle>
        <IconButton
          aria-label="close"
          onClick={handleCloseMath}
          sx={{
            position: 'absolute',
            right: 8,
            top: 8,
            color: (theme) => theme.palette.grey[500],
          }}
        >
          <CloseIcon />
        </IconButton>
        <Math darkMode={darkMode}/>
      </BootstrapDialog>
      
      <BootstrapDialog
        onClose={handleClosePortfolio}
        aria-labelledby="customized-dialog-title"
        open={openPortfolio}
      >
        <DialogTitle sx={{ m: 0, p: 2, bgcolor: darkMode ? themes.dark.backgroundColor : themes.light.backgroundColor, color: darkMode ? themes.dark.text : themes.light.textColor }} id="customized-dialog-title">
          Portfolio
        </DialogTitle>
        <IconButton
          aria-label="close"
          onClick={handleClosePortfolio}
          sx={{
            position: 'absolute',
            right: 8,
            top: 8,
            color: (theme) => theme.palette.grey[500],
          }}
        >
          <CloseIcon />
        </IconButton>
        <Portfolio darkMode={darkMode}/>
      </BootstrapDialog>

      <BootstrapDialog
        onClose={handleCloseAndroid}
        aria-labelledby="customized-dialog-title"
        open={openAndroid}
      >
        <DialogTitle sx={{ m: 0, p: 2, bgcolor: darkMode ? themes.dark.backgroundColor : themes.light.backgroundColor, color: darkMode ? themes.dark.text : themes.light.textColor }} id="customized-dialog-title">
          Android Studio
        </DialogTitle>
        <IconButton
          aria-label="close"
          onClick={handleCloseAndroid}
          sx={{
            position: 'absolute',
            right: 8,
            top: 8,
            color: (theme) => theme.palette.grey[500],
          }}
        >
          <CloseIcon />
        </IconButton>
        <Android darkMode={darkMode}/>
      </BootstrapDialog>

      <BootstrapDialog
        onClose={handleCloseWeb}
        aria-labelledby="customized-dialog-title"
        open={openWeb}
      >
        <DialogTitle sx={{ m: 0, p: 2, bgcolor: darkMode ? themes.dark.backgroundColor : themes.light.backgroundColor, color: darkMode ? themes.dark.text : themes.light.textColor }} id="customized-dialog-title">
          Website
        </DialogTitle>
        <IconButton
          aria-label="close"
          onClick={handleCloseWeb}
          sx={{
            position: 'absolute',
            right: 8,
            top: 8,
            color: (theme) => theme.palette.grey[500],
          }}
        >
          <CloseIcon />
        </IconButton>
        <Web darkMode={darkMode}/>
      </BootstrapDialog>
        </React.Fragment>
    );
};

export default MediaCard;
