import React, { useRef, useState, useEffect }  from 'react';
import Box from '@mui/material/Box';
//import Images from './images';
import Button from '@mui/joy/Button';
import { styled } from '@mui/system';
import { useThemeContext } from '../Burger/themeContext';
import themes from '../Burger/theme';
import LinearProgress, { linearProgressClasses } from '@mui/material/LinearProgress';
import Card from '@mui/joy/Card';
import CardCover from '@mui/joy/CardCover';
import CardContent from '@mui/joy/CardContent';
import Typography from '@mui/joy/Typography';
import LocationOnRoundedIcon from '@mui/icons-material/LocationOnRounded';
import  diplome  from './../../img/diplome2.jpg';
import  diplome2  from './../../img/remisediplome.jpg';
import { useInView } from 'react-intersection-observer';
import CV from './../../img/cv.png';
import './home.css';
import { useTranslation } from 'react-i18next';

function Home() {
  const {darkMode} = useThemeContext();
  const skillsRef = useRef();
  const { t } = useTranslation();

  const scrollToSkills = () => {
    skillsRef.current.scrollIntoView({ behavior: 'smooth' });
  };

  const handleTelechargerCV = () => {
    const url = './../../pdf/Louise_SANCHEZ_CV.pdf';
    
    const link = document.createElement('a');
    link.href = url;
    link.download = 'Louise_SANCHEZ_CV.pdf';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };
  
  const CustomButton = styled(Button)({
    backgroundColor: themes.dark.primaryColor,
    borderColor: themes.dark.primaryColor,
    '&:hover': {
      borderColor: '#754de8',
      backgroundColor: '#000000',
    },
  });

  const CustomOutlinedButton = styled(Button)({
    borderColor: themes.dark.primaryColor,
    color: themes.dark.primaryColor,
    '&:hover': {
      borderColor: themes.dark.textWhite,
      color: themes.dark.textWhite,
      backgroundColor: '#000000',
    },
  });

  const BorderLinearProgress = styled(LinearProgress)(({ theme }) => ({
    height: 8, width: 400, margin : 5,
      borderRadius: 5,
      backgroundColor: darkMode ? '#353436' : '#f1f1f1',
      '& .MuiLinearProgress-bar': {
        backgroundColor: darkMode ? themes.dark.primaryColor : themes.light.primaryColor,
      }
    }));

    const AnimatedProgressBar = ({ value }) => {
      const [progress, setProgress] = useState(0);
      const [ref, inView] = useInView({ threshold: 0 });
    
      useEffect(() => {
        let animation = null;
        if (inView) {
          animation = setInterval(() => {
            if (progress < value) {
              setProgress(prevProgress => prevProgress + 2);
            }
          }, 20); // Adjust speed of animation if needed
        } else {
          clearInterval(animation);
        }
        return () => clearInterval(animation);
      }, [inView, progress, value]);
    
      return (
        <div ref={ref} style={{ width: '100%' }}>
          <BorderLinearProgress variant="determinate" value={progress}/>
        </div>
      );
    };

  return (
    <Box
      component="main"
      sx={{
        flexGrow: 1,
        p: 3,
        backgroundColor: darkMode? themes.dark.backgroundColor : themes.light.backgroundColor,
        color: darkMode? themes.dark.text : themes.light.textColor,
      }}
    >
      <div>
          {/* <Images></Images> */}
          <Box sx={{ minHeight: '100vh', margin: '3%'}}>
          <Box sx={{ display: 'flex', flexWrap: 'wrap', justifyContent: 'space-around', bgcolor: darkMode? themes.dark.encadre : themes.light.encadre, borderRadius: '10px', padding: '4%'}}>
          <Box sx={{width: { sm: '70%', md: '55%' }, textAlign: 'justify'}}>
          <Typography style={{ fontSize: '2.6rem', textAlign: 'left', fontFamily: '"Comfortaa", sans-serif', color: darkMode? themes.dark.text : themes.light.textColor}}>{t('BIENVENUE')}</Typography><br></br>
          <Typography style={{ fontSize: '1.2rem', fontFamily: "'Lexend Giga', sans-serif", textAlign: 'left', color: darkMode? themes.dark.text : themes.light.textColor}}> {t('PRESENTATION')}</Typography> <br></br>
          <Typography sx={{color: darkMode? themes.dark.text : themes.light.textColor}}>{t('DETAIL')}</Typography><br></br>
          <Typography sx={{color: darkMode? themes.dark.text : themes.light.textColor}}>{t('DECOUVRIR')}</Typography><br></br>
          <Typography sx={{color: darkMode? themes.dark.text : themes.light.textColor}}>{t('BUTTONPHRASE')}</Typography><br></br>
          {/* <CustomButton size="lg" variant="solid" sx={{marginRight: '20px'}} onClick={scrollToSkills}>Large</CustomButton> */}
          <CustomOutlinedButton size="lg" variant="outlined" onClick={scrollToSkills}>{t('BUTTON')}</CustomOutlinedButton>
          </Box>
          <Card sx={{ minHeight: '400px', width: 320, border: 'none' }}>
      <CardCover>
        <img
          src={diplome2}
          loading="lazy"
          alt=""
        />
      </CardCover>
      <CardCover
        sx={{
          background:
            'linear-gradient(to top, rgba(0,0,0,0.4), rgba(0,0,0,0) 200px), linear-gradient(to top, rgba(0,0,0,0.8), rgba(0,0,0,0) 300px)',
        }}
      />
      <CardContent sx={{ justifyContent: 'flex-end' }}>
        <Typography level="title-lg" textColor="#fff">
          Remise des Diplomes
        </Typography>
        <Typography
          startDecorator={<LocationOnRoundedIcon />}
          textColor="neutral.300"
        >
          Centre International de Valbonne
        </Typography>
      </CardContent>
    </Card>
    </Box>
          </Box>


          <Box ref={skillsRef} sx={{ bgcolor: darkMode? themes.dark.encadre : themes.light.encadre, borderRadius: '10px', padding: '50px', margin:'3%'}}>
          <Typography style={{ color: darkMode? themes.dark.text : themes.light.textColor, textAlign: 'center', marginBottom: '30px', fontSize: '2.6rem' }}>{t('MESCOMPETENCES')}</Typography> <br></br><br></br>
          <Box sx={{ display:'flex', flexWrap: 'wrap', justifyContent:'space-around'}}>
          <Box sx={{display:'flex', flexDirection: 'column', flexWrap: 'wrap', justifyContent:'normal'}}>
          <Box>
          <h2>BACK-END</h2> <br></br>
          <h3>Typescript / Javascript</h3>
          <AnimatedProgressBar value={80} />
          <h3>Java (Maven, Spring, Junit, Mockito)</h3>
          <AnimatedProgressBar value={60} />
          <h3>Python</h3>
          <AnimatedProgressBar value={50} />
          <h3>PHP</h3>
          <AnimatedProgressBar value={20} />
          </Box><br></br>
          <Box>
          <h2>FRONT-END</h2> <br></br>
          <h3>HTML / CSS</h3>
          <AnimatedProgressBar value={80} />
          <h3>React (Rdeux)</h3>
          <AnimatedProgressBar value={80} />
          <h3>Angular</h3>
          <AnimatedProgressBar value={35} />
          </Box>
          </Box>
          <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
          <Card sx={{ minHeight: '600px', minWidth: 420, border: 'none' }}>
      <CardCover>
        <img
          src={CV}
          loading="lazy"
          alt=""
        />
      </CardCover>
      <CardCover/>
    </Card> <br></br>
    <CustomOutlinedButton size="lg" variant="outlined" onClick={handleTelechargerCV}>{t('TELECHARGER')}</CustomOutlinedButton>
    </Box>
    </Box>
    </Box>
          </div>
    </Box>
  );
};

export default Home;